contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address log1, address log2, uint256 minSumAfter) internal {
        bool r1;
        try c.SetLogFile(log1) { r1 = false; } catch { r1 = true; }
        try c.Initialized() {} catch { return; }
        bool r2;
        try c.SetLogFile(log2) { r2 = false; } catch { r2 = true; }
        bool r3;
        try c.SetMinSum(minSumAfter) { r3 = false; } catch { r3 = true; }
        assertTrue(!r1 && r2 && r3);
    }

    function testFuzz_run(address log1, address log2, uint256 minSumAfter) public {
